const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const rawInputs = $input.all();
if (!rawInputs.length) throw new Error('媒体上传适配器没有收到输入');
const descriptors = rawInputs.flatMap((item, originalIndex) => {
  const value = item.json?.input ?? item.json ?? {};
  return Array.isArray(value.inputs)
    ? value.inputs.map((source) => ({ source, originalIndex }))
    : [{ source: value, originalIndex, legacyBinary: item.binary?.data }];
});
const platform = (value) => process.platform === 'win32' ? value.toLowerCase() : value;
const inside = (root, candidate) => {
  const relative = path.relative(root, candidate);
  return Boolean(relative) && !relative.startsWith('..' + path.sep) && !path.isAbsolute(relative);
};
const hashFile = (filePath) => new Promise((resolve, reject) => {
  const hash = crypto.createHash('sha256');
  const stream = fs.createReadStream(filePath);
  stream.on('error', reject);
  stream.on('data', (chunk) => hash.update(chunk));
  stream.on('end', () => resolve(hash.digest('hex')));
});
const prepareOne = async (wrapper, fallbackIndex) => {
  const source = wrapper.source || {};
  const legacyBinary = wrapper.legacyBinary;
  const startedAt = Date.now();
  if ((!source.sourcePath || !source.taskRoot) && legacyBinary?.data) {
    const buffer = Buffer.from(String(legacyBinary.data), 'base64');
    const mimeType = String(legacyBinary.mimeType || source.mimeType || '').toLowerCase();
    const mediaType = mimeType === 'video/mp4' ? 'video' : mimeType.startsWith('image/') ? 'image' : '';
    if (!mediaType || !['image/jpeg','image/png','image/webp','video/mp4'].includes(mimeType)) throw new Error('旧版单资源输入的媒体 MIME 不受支持');
    const validSignature = mimeType === 'video/mp4'
      ? buffer.length >= 12 && buffer.toString('ascii',4,8) === 'ftyp'
      : mimeType === 'image/png'
        ? buffer.subarray(0,8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]))
        : mimeType === 'image/jpeg'
          ? buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff
          : buffer.toString('ascii',0,4) === 'RIFF' && buffer.toString('ascii',8,12) === 'WEBP';
    if (!validSignature) throw new Error('旧版单资源输入的文件签名与 MIME 不一致');
    const sourceSha256 = crypto.createHash('sha256').update(buffer).digest('hex');
    const inputIndex = Number(source.inputIndex ?? fallbackIndex);
    return {
      json: {
        ...source,
        sourceFileName: String(source.sourceFileName || legacyBinary.fileName || ('media-' + inputIndex)),
        inputIndex,
        mediaType,
        mimeType,
        sourceSha256,
        uploadedSha256: sourceSha256,
        sourceSizeBytes: buffer.length,
        uploadedSizeBytes: buffer.length,
        cacheHit: false,
        compressionRatio: 1,
        uploadAttempt: Number(source.uploadAttempt || 0),
        initialUrlReused: false,
        startedAt,
        skipUpload: false
      },
      binary: { data: legacyBinary },
      pairedItem: { item: wrapper.originalIndex ?? fallbackIndex }
    };
  }
  const sourcePath = path.resolve(String(source.sourcePath || ''));
  const taskRoot = path.resolve(String(source.taskRoot || ''));
  if (!path.isAbsolute(sourcePath) || !path.isAbsolute(taskRoot) || !fs.existsSync(taskRoot)) throw new Error('媒体上传缺少安全的绝对 sourcePath/taskRoot');
  const rootInfo = fs.lstatSync(taskRoot);
  const sourceInfo = fs.lstatSync(sourcePath);
  if (!rootInfo.isDirectory() || rootInfo.isSymbolicLink() || !sourceInfo.isFile() || sourceInfo.isSymbolicLink()) throw new Error('媒体路径必须是任务根目录内的普通文件');
  const rootReal = fs.realpathSync(taskRoot);
  const sourceReal = fs.realpathSync(sourcePath);
  if (!inside(rootReal, sourceReal)) throw new Error('媒体文件逃逸 OZON 任务根目录');
  const expectedSha256 = String(source.expectedSha256 || source.sha256 || '').replace(/^sha256:/i,'').toLowerCase();
  const actualUploadSha256 = await hashFile(sourceReal);
  if (!/^[a-f0-9]{64}$/.test(expectedSha256) || actualUploadSha256 !== expectedSha256) throw new Error('媒体 SHA-256 与任务契约不一致: ' + path.basename(sourceReal));
  if (Number(source.expectedSizeBytes || sourceInfo.size) !== sourceInfo.size) throw new Error('媒体大小与任务契约不一致: ' + path.basename(sourceReal));
  const mediaType = String(source.mediaType || '').toLowerCase();
  const mimeType = String(source.mimeType || '').toLowerCase();
  if (!['image','video'].includes(mediaType) || !['image/jpeg','image/png','image/webp','video/mp4'].includes(mimeType)) throw new Error('媒体类型或 MIME 不受支持');
  const uploadPath = sourceReal;
  const uploadedSha256 = actualUploadSha256;
  const uploadedSizeBytes = sourceInfo.size;
  const cacheHit = Boolean(source.cacheHit);
  const compressionRatio = Number(source.compressionRatio || 1);
  const priorUrl = String(source.priorUrl || '').trim();
  const reusedUrl = /^https?:\/\//i.test(priorUrl);
  const inputIndex = Number(source.inputIndex ?? fallbackIndex);
  const sourceFileName = String(source.sourceFileName || path.basename(sourceReal));
  const common = {
    ...source,
    sourceFileName,
    inputIndex,
    mediaType,
    mimeType,
    sourcePath: sourceReal,
    taskRoot: rootReal,
    sourceSha256: String(source.sourceSha256 || source.originalSourceSha256 || actualUploadSha256),
    uploadedSha256,
    sourceSizeBytes: sourceInfo.size,
    uploadedSizeBytes,
    cacheHit,
    compressionRatio,
    uploadKey: String(source.uploadKey || ''),
    profileKey: String(source.profileKey || ''),
    profileVersion: String(source.profileVersion || ''),
    assignments: Array.isArray(source.assignments) ? source.assignments : [],
    uploadPath,
    uploadAttempt: Number(source.uploadAttempt || 0),
    initialUrlReused: reusedUrl,
    startedAt,
    skipUpload: reusedUrl,
    url: reusedUrl ? priorUrl : undefined
  };
  if (reusedUrl) return { json: common, pairedItem: { item: fallbackIndex } };
  const buffer = fs.readFileSync(uploadPath);
  return {
    json: common,
    binary: { data: { data: buffer.toString('base64'), mimeType, fileName: path.basename(uploadPath), fileExtension: path.extname(uploadPath).slice(1), fileSize: String(buffer.length) } },
    pairedItem: { item: fallbackIndex }
  };
};
return Promise.all(descriptors.map(prepareOne));

const prepared = $('准备上传输入').all();
