  let source = prepared[index]?.json || {};
  try { source = $('准备上传输入').itemMatching(index).json || source; } catch {}
  const body = item.json?.body !== undefined ? item.json.body : item.json;
  const candidates = [
    body?.url, body?.object, body?.data?.url, body?.data?.object, body?.file?.url, body?.data?.file?.url,
    body?.download_url, body?.data?.download_url
  ];
  const url = candidates.map((value) => String(value || '').trim()).find((value) => /^https?:\/\//i.test(value));
  if (!url) return {
    json: {
      ...source,
      uploadResponseReady: false,
      urlReady: false,
      urlVerificationAttempt: 0,
      urlVerificationStatus: 'UPLOAD_RESPONSE_INVALID',
      urlVerificationReasons: ['UPLOAD_RESPONSE_INVALID'],
      verificationHttpStatus: Number(item.json?.statusCode || 0),
