    reasons: Array.isArray(value.urlVerificationReasons) ? value.urlVerificationReasons : ['UNKNOWN'],
    retryable: true
  };
  return { json: {
    ok: valid,
    retryable: valid ? false : error.retryable !== false,
    sourceFileName: String(value.sourceFileName),
    uploadKey: String(value.uploadKey || ''),
    inputIndex: Number(value.inputIndex ?? index),
    mediaType: String(value.mediaType),
    mimeType: String(value.mimeType),
    url: verifiedUrl,
