  const incomingKey = String(incoming.uploadKey || '');
  const incomingIndex = Number(incoming.inputIndex);
  const lineageIndex = pairedIndex(item);
  if (incomingKey && byUploadKey.has(incomingKey)) source = byUploadKey.get(incomingKey);
  else if (Number.isInteger(incomingIndex) && byInputIndex.has(incomingIndex)) source = byInputIndex.get(incomingIndex);
  else if ((!source || !String(source.uploadKey || '')) && Number.isInteger(lineageIndex) && byInputIndex.has(lineageIndex)) source = byInputIndex.get(lineageIndex);
  const uploadKey = String(source.uploadKey || '');
  const inputIndex = Number(source.inputIndex);
  if (!uploadKey || !Number.isInteger(inputIndex)) throw new Error('无法按 uploadKey/inputIndex 关联媒体上传失败项');
  const rawError = incoming.error && typeof incoming.error === 'object' ? incoming.error : {};
  const statusCode = Number(incoming.statusCode || rawError.statusCode || rawError.httpCode || 0);
  const reasons = ['UPLOAD_REQUEST_FAILED', statusCode > 0 ? 'HTTP_' + statusCode : 'NO_STATUS'];
  const retryable = statusCode === 0 || statusCode === 408 || statusCode === 429 || statusCode >= 500;
