  const contentType = rawContentType.split(';')[0].trim();
  const mediaType = String(source.mediaType || '').toLowerCase();
  const reasons = [];
  let downloadedSizeBytes = 0;
  let downloadedSha256 = '';
  if (response.error) reasons.push('NETWORK_ERROR');
  if (statusCode !== 200) reasons.push('HTTP_' + String(statusCode || 'NO_STATUS'));
  if (mediaType === 'image') {
    const allowedMimeTypes = new Set(['image/jpeg','image/png','image/webp']);
    if (!allowedMimeTypes.has(contentType) || contentType !== String(source.mimeType || '').toLowerCase()) reasons.push('MIME_MISMATCH');
    let buffer = null;
