      if (declaredLength > 0 && declaredLength !== downloadedSizeBytes) reasons.push('CONTENT_LENGTH_MISMATCH');
    }
  } else if (mediaType === 'video') {
    if (!contentType.startsWith('video/')) reasons.push('MIME_MISMATCH');
  } else {
    reasons.push('UNSUPPORTED_MEDIA_TYPE');
  }
  const valid = reasons.length === 0;
  output.push({
    json: {
      ...source,
      urlReady: valid,
      urlVerificationAttempt: 4,
      urlVerificationStatus: valid ? 'VALID' : 'INVALID',
      urlVerificationReasons: reasons,
      verificationHttpStatus: statusCode,
      verificationContentType: contentType,
      downloadedSizeBytes,
      downloadedSha256,
      verifiedAt: valid ? new Date().toISOString() : undefined
    },
    pairedItem: { item: Number(source.inputIndex ?? index) }
  });
}
return output;
